import Grid from "@mui/material/Grid/Grid";
import Typography from "@mui/material/Typography/Typography";
import JohnHairImage from "../assets/images/work/johnhair.avif";
import TherapistiImage from '../assets/images/work/therapisti.svg';
import HFNImage from '../assets/images/work/hfn_logo.webp';
import BoldingatlanImage from '../assets/images/work/boldingatlan.png';
import BLMProConstructImage from '../assets/images/work/blm-pro-construct-logo.png';
import { Box, Chip } from "@mui/material";
import useImageLoading from "../hooks/use-image-loading";
import Tilt from 'react-parallax-tilt';

const styles = {
  chip: {
    mx: 'auto',
    my: 4,
  },
  imageWrapper: {
    height: { xs: 60, sm: 90 },
    border: '1px solid rgba(255, 255, 255, 0.08)',
    borderRadius: '12px',
    padding: '20px',
    background: 'rgba(255, 255, 255, 0.04)',
    backdropFilter: 'blur(20px)',
    WebkitBackdropFilter: 'blur(20px)',
    boxShadow: '0 4px 24px rgba(0, 0, 0, 0.4)',
    transition: 'border-color 300ms ease-in-out, box-shadow 300ms ease-in-out, background 300ms ease-in-out',
    cursor: 'pointer',
    textDecoration: 'none',
    display: 'block',
    '&:hover': {
      borderColor: 'rgba(133, 196, 103, 0.5)',
      boxShadow: '0 8px 32px rgba(133, 196, 103, 0.15)',
      background: 'rgba(255, 255, 255, 0.07)',
    }
  },
  image: {
    height: '100%',
    width: '100%',
    objectFit: 'scale-down'
  }
};

type Project = {
  image: string;
  url?: string;
  comingSoon?: boolean;
};

const projects: Project[] = [
  { image: TherapistiImage, url: "https://therapisti.ro" },
  { image: HFNImage, url: "https://hargitafightnight.ro" },
  { image: BoldingatlanImage, url: "https://boldingatlan.hu" },
  { image: JohnHairImage, url: "https://johnhair.ro" },
  { image: BLMProConstructImage, comingSoon: true },
];

export const MyWorks = () => {
  const { onImageLoad } = useImageLoading();

  return (
    <Grid pt={3} width="100%" id="work">
      <Typography variant="h3" sx={{ color: 'text.primary' }}>
        my recent work
      </Typography>
      <Typography variant="body2" pt={2} sx={{ color: '#8d8d8d' }}>
        Here are a few past projects I've worked on.
      </Typography>
      <Grid container pt={3} gap={3} justifyContent="center">
        {projects.map((project, i) => (
          <Grid key={i} item xs={12} sm={6} md={4} lg={3}>
            <Tilt
              tiltMaxAngleX={10}
              tiltMaxAngleY={10}
              glareEnable={true}
              glareMaxOpacity={0.08}
              glareColor="#85c467"
              glarePosition="all"
              scale={1.03}
              transitionSpeed={400}
              style={{ borderRadius: '12px', display: 'block' }}
            >
              <Box
                component={project.url ? 'a' : 'div'}
                href={project.url}
                target={project.url ? '_blank' : undefined}
                rel={project.url ? 'noreferrer' : undefined}
                sx={{
                  ...styles.imageWrapper,
                  position: 'relative',
                  ...(project.url ? {} : { cursor: 'default', '&:hover': {} }),
                }}
              >
                <Box
                  component="img"
                  className="smooth-loading"
                  onLoad={onImageLoad}
                  src={project.image}
                  sx={styles.image}
                />
                {project.comingSoon && (
                  <Chip
                    label="coming soon"
                    size="small"
                    sx={{
                      position: 'absolute',
                      top: -15,
                      right: -5,
                      background: 'rgba(133, 196, 103, 0.15)',
                      border: '1px solid rgba(133, 196, 103, 0.4)',
                      color: '#85c467',
                      fontSize: '0.65rem',
                      fontWeight: 600,
                      letterSpacing: '0.5px',
                    }}
                  />
                )}
              </Box>
            </Tilt>
          </Grid>
        ))}
      </Grid>
    </Grid>
  );
}
